template:
% 参数由系统自动注入：\def\a{1} \def\showextrema{1} \def\showasym{1} \def\showpoint{0} \def\px{2} \def\labelp{P}
% 极值点坐标
\pgfmathsetmacro{\sa}{sqrt(\a)}
\pgfmathsetmacro{\ya}{2*\sa}
% 点 P 纵坐标
\pgfmathsetmacro{\py}{\px+\a/\px}
% 视图半宽：以极值点和点 P 为特征，过远封顶
\pgfmathsetmacro{\hfeat}{max(\sa+1.0, abs(\px)+0.8)}
\pgfmathsetmacro{\hval}{max(\hfeat, \ya+0.7, abs(\py)+0.7)}
\pgfmathsetmacro{\hh}{min(\hval, \hfeat+4.0)}
\pgfmathtruncatemacro{\xright}{ceil(\hh)}
\pgfmathtruncatemacro{\ytop}{\xright}
\pgfmathtruncatemacro{\xleft}{-\xright}
\pgfmathtruncatemacro{\ybottom}{-\ytop}
% 曲线截断：解方程 x+a/x=Y 的两个根（近 y 轴端、远侧端）
\pgfmathsetmacro{\yy}{\ytop+0.3}
\pgfmathsetmacro{\disc}{sqrt(\yy*\yy-4*\a)}
\pgfmathsetmacro{\xn}{(\yy-\disc)/2}
\pgfmathsetmacro{\xf}{(\yy+\disc)/2}
\pgfmathsetmacro{\dhi}{min(\xf,\xright)}
\pgfmathsetmacro{\xrange}{\xright-\xleft}
\pgfmathsetmacro{\figscale}{6.5/\xrange}
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ===== 坐标系 =====
  \draw[->, thick] (\xleft-0.5,0) -- (\xright+0.6,0) node[right] {$x$};
  \draw[->, thick] (0,\ybottom-0.5) -- (0,\ytop+0.6) node[above] {$y$}; % ===== 斜渐近线 y=x =====
  \ifnum\showasym>0
    \draw[dashed, gray] (\xleft,\xleft) -- (\ytop,\ytop);
    \node[font=\tiny, gray, anchor=north west] at (\xleft+0.3,\xleft+0.3) {$y=x$};
  \fi
  % ===== 曲线 y=x+a/x（两支）=====
  \draw[thick, domain=\xn:\dhi, samples=100, smooth] plot (\x, {\x+\a/\x});
  \draw[thick, domain=-\dhi:-\xn, samples=100, smooth] plot (\x, {\x+\a/\x});
  \node[font=\tiny, anchor=east] at (\dhi-0.15,\ytop-1.1) {$y=x+\dfrac{a}{x}$};
  % ===== 极值点 A、B =====
  \ifnum\showextrema>0
    \fill (\sa,\ya) circle [radius=\dotr pt];
    \node[above right, font=\tiny] at (\sa,\ya) {$A$};
    \fill (-\sa,-\ya) circle [radius=\dotr pt];
    \node[below left, font=\tiny] at (-\sa,-\ya) {$B$};
  \fi
  % ===== 曲线上点 P =====
  \ifnum\showpoint>0
    \fill (\px,\py) circle [radius=\dotr pt];
    \node[above right, font=\tiny] at (\px,\py) {$\labelp$};
  \fi
\end{tikzpicture}
